INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('1', '10017', '1.1.1', 'Assess the external environment', 'Assessing all forces, entities, and systems that are external to an organization but can affect its operation. Analyze far-reaching currents in the macroeconomic situation, assess the competition, evaluate technological changes, and identify societal as well as ecological issues of concern. Create a big-picture understanding of externalities, with sufficient depth across individual aspects.', '1'),
('2', '10018', '1.1.2', 'Survey market and determine customer needs and wants', 'Examining the market to identify customer required solutions. Assess the relevant market(s) to determine the products/services that are needed or wanted by customers. Carry out quantitative and qualitative analyses to capture and investigate products/services. Employ creative techniques that allow for a closer appreciation of the customer, and design relevant solutions.', '1'),
('3', '10019', '1.1.3', 'Assess the internal environment', 'Undertaking a review of the organization''s in-house skills and resources in order to create a big-picture understanding of internal capacities. Assess the organization''s capabilities in order to advance the advantageous and weed out the detrimental aspects. Identify synergic associations within the backdrop of the forces and players active in the market, and take into account all externalities.', '1'),
('4', '10020', '1.1.4', 'Establish strategic vision', 'Establishing the organization''s long-term vision as a strategic positioning and engagement of stakeholders. Institute the vision by creating strategic orientations of all stakeholders. Understand the strategy development frameworks in this context.', '1'),
('5', '16792', '1.1.5', 'Conduct organization restructuring opportunities', 'Examining the scope and contingencies for restructuring based on market situation and internal realities. Map the market forces over which any and all probabilities can be probed for utility and viability. Once the restructuring options have been analyzed and the due-diligence performed, execute the deal. Consider seeking professional services for assistance in formalizing these opportunities.', '1'),
('6', '10037', '1.2.1', 'Develop overall mission statement', 'Establishing an overarching, compact statement that concisely underscores the mission of the organization. Define and communicate a clear and succinct mission statement, which encapsulates how the organization aims to proceed in order to Establish a strategic vision [10020]. Solicit critical inputs from senior management and strategy executives, and collaborate with marketing or personnel from allied functions.', '2'),
('7', '10038', '1.2.2', 'Define and evaluate strategic options to achieve the objectives', 'Assessing sets of strategic decisions designed to drive the organization''s long-term objectives. Identify various strategies concerning core functional areas. Appraise strategic options in light of auxiliary decision frameworks that ensure smooth functioning, the advancement of functional efficiencies, and vitality. Involve senior management executives, especially strategy and/or business unit personnel, with need-based consultative assistance from professional services providers.', '2'),
('8', '10039', '1.2.3', 'Select long-term business strategy', 'Developing a strategy for the achievement of business goals over the distant future. Adopt one of the strategic options for realizing its mission over the long term. Enlist senior management executives, comprising strategy and/or business unit personnel.', '2'),
('9', '10040', '1.2.4', 'Coordinate and align functional and process strategies', 'Aligning the approach and method of individual units, departments, systems, and operations within the organization, in accordance with the larger strategic course adopted. Employ the organization''s strategic path to guide the functions, divisions, and operations. Calibrate the plan and method of each functional area, as well as the processes therein, to Select the long-term business strategy [10039].', '2'),
('10', '10041', '1.2.5', 'Create organizational design', 'Formulating a design for the organization''s resources that allow it to meet its objectives. Develop a new framework for molding the organization''s various processes into a coherent and seamless whole.', '2'),
('11', '10042', '1.2.6', 'Develop and set organizational goals', 'Developing overall goals for the organization that help in accomplishing its mission. Formulate organization-wide targets in the near to middle term, which will accumulate and propel the organization to realize its long-term objectives, as outlined in Develop an overall mission statement [10037]. Enlist business unit heads or equivalent personnel, in close collaboration with senior management executives.', '2'),
('12', '10043', '1.2.7', 'Formulate business unit strategies', 'Charting a strategic course for business units in order to leverage opportunities, sidestep hurdles, and create synergies among each other. Create strategic road maps for the organization''s units--in light of their individual resources and requirements, as well as their relationships with other business units--to achieve organizational goals.', '2'),
('13', '19959', '1.2.8', 'Develop customer experience strategy', 'Defining a roadmap to meet customer expectations while considering how it will affect the business.', '2'),
('14', '18916', '1.2.9', 'Communicate strategies internally and externally', 'Conveying planned procedures and methods to both internal departments and external stakeholders like customers, suppliers, etc., in an effective manner based on organizational objective.', '2'),
('15', '12748', '1.3.1', 'Develop Over The Counter (OTC)/generic business', NULL, '3'),
('16', '17665', '1.3.2', 'Develop healthcare services business', NULL, '3'),
('17', '17666', '1.3.3', 'Develop integrated technology/medical services business', NULL, '3'),
('18', '12749', '1.3.4', 'Network for new business', NULL, '3'),
('19', '12750', '1.3.5', 'Obtain new business financing', NULL, '3'),
('20', '12751', '1.3.6', 'Structure contracts /milestones /accounting/tax', NULL, '3'),
('21', '12741', '1.3.7', 'Arrange licensing (in/out)', NULL, '3'),
('22', '12742', '1.3.8', 'Develop capitation programs', NULL, '3'),
('23', '12743', '1.3.9', 'Develop joint ventures', NULL, '3'),
('24', '12744', '1.3.10', 'Perform acquisitions', NULL, '3'),
('25', '10057', '1.3.11', 'Develop strategic initiatives', 'Developing strategic projects that help fulfill long-term goals. Develop time-bound projects that are discretionary in nature and lie beyond the scope of the organization''s routine operations.', '3'),
('26', '10058', '1.3.12', 'Evaluate strategic initiatives', 'Examining projects of strategic significance that lie outside the purview of the organization''s routine operations. Closely analyze strategic initiatives for their applicability and feasibility, given the organization''s vision.', '3'),
('27', '10059', '1.3.13', 'Select strategic initiatives', 'Selecting relevant projects of strategic significance that create opportunities for the organization to realize its long-term objectives, on the basis of their suitability to the organization''s constraints and reality. Select from the process Evaluate strategic initiatives [10058], based on their applicability and feasibility for the organization. Enlist senior management, especially strategy personnel.', '3'),
('28', '10060', '1.3.14', 'Establish high-level measures', 'Devising measures to examine strategic projects. Formulate evaluation criteria to assess the strategic initiatives for the level of impact.', '3'),
('29', '19507', '1.3.15', 'Execute strategic initiatives', 'Successfully implement strategic initiatives. Execution of strategy is also defined as the process of implementing logical set of connected activities by an organization to make a strategy work.', '3'),
('30', '20945', '1.4.1', 'Develop business models', 'Creating an economic model that describes the goals of an organization and the business processes needed to achieve those goals. This involves information gathering, securing necessary approvals and authorizations, integrating with preexisting models, including the general business concept [10002] and business strategy [10015], and formally accepting the model as the basis for organization''s day-to-day operations.', '4'),
('31', '20950', '1.4.2', 'Maintain business models', 'Revising and updating business models to reflect the changes in the marketed services, product inventory, market behavior, available resources or accrued expenses. Determine how and when to modify the accepted business model in response to incoming feedback.', '4'),
('32', '20955', '1.4.3', 'Establish business model governance', 'Creating and implementing a strategy, responsibilities and control mechanisms for managing business models that are timely, efficient and cost-effective.', '4'),
('33', '10061', '2.1.1', 'Manage product and service portfolio', 'Managing a portfolio of product/service offerings to take advantage of shifts in the market expectations, all the while coordinating with the overall business strategy. Revisit the product/service portfolio in light of market opportunities, and overhaul it to capture value created by these opportunities. Identify gaps between current offerings and the market expectations to direct the organization''s R&D activity. Create new solutions, and revise or retire existing ones so that the revamped portfolio aligns with Develop a business strategy [10015].', '5'),
('34', '10067', '2.1.2', 'Manage product and service life cycle', 'Manage the introduction and withdrawal of products/services. Administer associated changes, namely measuring the performance of new solution offerings and the revision of master files in the archives.', '5'),
('35', '19985', '2.1.3', 'Manage patents, copyrights, and regulatory requirements', 'Determining the attributes necessary to protect and safeguard intellectual assets, maximize the value of IP assets through streamlined process, and collaboration between departments. Focus on needs to safeguard, critical assets, and assets'' value.', '5'),
('36', '11740', '2.1.4', 'Manage product and service master data', 'Controlling/authorizing to enable services'' and products'' data and other critical data of these functions through a well secured storage and accessibility processes backed by siloed applications/IT systems.', '5'),
('37', '12753', '2.2.1', 'Manage research', 'Identifying and validating a target such as a drug or biochemical substance, or a cell in an organism or organic sample and ends with the development of an assay.  An assay is an investigative (analytic) procedure in laboratory medicine, pharmacology, environmental biology, and molecular biology for qualitatively assessing or quantitatively measuring the presence or amount or the functional activity of the identified target.', '6'),
('38', '12757', '2.2.2', 'Perform research/ licensing', 'Performing acquisition and licensing of research knowledge, conducting basic research, and managing the corresponding technology and information to enable the targeting of the basic research efforts.', '6'),
('39', '10065', '2.3.1', 'Perform discovery research', 'Coordinating R&D activity to identify new technologies to integrate into the revamped portfolio of products/services. Conduct early-stage R&D activity to close gaps between existing solution offerings and changing market expectations. Triangulate appropriate technologies that can support the development of a revised product/service portfolio.', '7'),
('40', '19669', '2.3.2', 'Generate new product/service concepts', 'Producing and defining ideologies for new product/service offerings.', '7'),
('41', '19990', '2.3.3', 'Define product/service development requirements', 'Encompassing the identification and capture of new product/service requirements or potential improvements to current products/services. Collaborating with members of the supply chain to ensure the feasibility of what is being defined in the requirements. For example, a product with manufacturing requirements that supply chain cannot currently fulfill requires a corporate decision to either upgrade manufacturing capabilities or abandon the new product. Enterprise-level effects and needs must be considered. Depending on the nature of the final product or service, these requirements are often defined as a set of abilities, such as availability or reliability, that influence product development decisions.', '7'),
('42', '19993', '2.4.1', 'Design and prototype products and services', 'Sketching and standardizing product and service based on the market. Analyze the data market competitiveness and innovation attained for the product and service development.', '8'),
('43', '19996', '2.4.2', 'Test market for new or revised products and services', 'Expanding on the marketplace analysis that took place earlier in the product development lifecycle by testing the market against offerings. The results from this in-depth analysis will help the organization finalize product/service characteristics and technical requirements and also identify any needed changes in the manufacturing and delivery processes that support market delivery. To prepare a detailed market study that accounts for any changes in the global environment, the organization may want to conduct a series of interviews, workshops, and focus groups with potential and existing customers.', '8'),
('44', '19997', '2.4.3', 'Prepare for production/service delivery', 'Devising business plans and procedures for manufacturing/operations/production and delivery of services offered by the organization. Further in general terms the total amount of output that the manufacturing department is responsible to produce for each period.', '8'),
('45', '12763', '2.4.4', 'Compile and submit dossier', 'Defining regulatory strategy and new product profile and planning the structure (and components) of the registration dossier that is ultimately submitted to the regulatory authorities for approval.  The standard backbone and component templates of the dossier are created.  E.g., an eCTD (electronic Common Technical Document), a global standard that is comprised of 5 modules that is filed when a new drug application, is to be investigated. The dossiers are then assembled, the documentation (templates, metadata and formatting) standardized, and the lifecycle states and dates of the dossier and its components are tracked against the submission plan so that the submission process can be optimized.  Regulatory reviewers look at the documentation for non-clinical and CMC (Chemistry Manufacturing Control) submission components.  The registration dossier is compiled and submitted, and the speed of approvals is monitored.', '8'),
('46', '10106', '3.1.1', 'Perform customer and market intelligence analysis', 'Gathering intelligence on the market and customers. Closely examine the inherent attributes and collective behavior of the various market and customer segments. Track trends in the market. Determine what drives the customers to make purchasing decisions in order to identify opportunities in the market.', '9'),
('164', '10522', '7.7.1', 'Manage reporting processes', 'Providing information and reports regarding employees to management.', '34'),
('47', '10107', '3.1.2', 'Evaluate and prioritize market opportunities', 'Appraising market opportunities by quantifying and subjecting them to prioritization, as well as validation tests. Closely examine the market opportunities that have been identified by Perform customer and market intelligence analysis [10106]. Triangulate those opportunities to capitalize by finding a fit between identified opportunities and the composite of organizational capabilities and business strategy.', '9'),
('48', '11168', '3.2.1', 'Define offering and customer value proposition', 'Refining the attributes of organizational offerings to define their value proposition for the customer. Clearly define the suite of offerings in terms of the value delivered, from the perspective of what the customer desires. Validate the benefits delivered to the customers against target market segments, using techniques such as minimum viable product. Position brands for the respective products/services, in line with their unique value proposition and aligned with customers needs.', '10'),
('49', '10123', '3.2.2', 'Define pricing strategy', 'Creating a pricing strategy and mechanism that aligns with the benefits of the products/services, as perceived by customers. Chart a strategic course and a methodology that can guide the pricing of products/services. Draw heavily from the customer value proposition, and balance the expectations of different divisions inside the organization, while delivering the maximum ROI.', '10');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('50', '20000', '3.2.3', 'Define and manage channel strategy', 'Establishing all the activities needed to identify the appropriate channels to market to different customer segments as defined in Determine target segments [10117]. This involves finding channel partners, ensuring that the channels align with organizational strategy for each segment, and the final channel selection process.', '10'),
('51', '20006', '3.2.4', 'Analyze and manage channel performance', 'Monitoring marketing and distribution efforts of all channels individually and as a network. Re-distribute or add resources to channels that perform better than expected. Purge or consolidate under-performing channels, and find more promising replacements.', '10'),
('52', '16848', '3.2.5', 'Develop marketing communication strategy', 'Establishing marketing communications that deliver promotional messages, in a coordinated way, through multiple marketing channels, such as print, radio, television, direct mail, online or mobile advertising, email, social media or personal selling.', '10'),
('53', '18924', '3.2.6', 'Design and manage customer loyalty program', 'Creating and managing a customer loyalty program. The loyalty program is a key part of marketing, with an elaborate strategy and process for acquiring, retaining, and engaging with members. Members are engaged and acquainted to the loyalty program, thus growing relationship and adding value through the program. ', '10'),
('54', '10148', '3.3.1', 'Establish goals, objectives, and metrics for products/services by channel/segment', 'Determining what to achieve by marketing. Create qualitative and quantitative targets. Establish metrics to track performance (for individual Market segments [10109] and Channels for target segments [10129]). Enlist the head of marketing to determine marketing priorities and the related measures. (The decision in establishing these goals, objectives, and metrics is founded in Develop marketing strategy [10102] and takes cues from current priorities and organizational strategy.)', '11'),
('55', '10149', '3.3.2', 'Establish marketing budgets', 'Creating a budget for the organization''s marketing efforts, in line with the business-wide strategic outlook. Create a plan to distribute resources for achieving the marketing strategy in light of the overall business strategy. Make cost assumptions; calculate the estimated total revenue from the marketing activities against the costs/expenses of these activities. Forecast the return on investment. Attribute costs to the appropriate marketing activities such as promotional campaigns, advertising, marketing communications, PR campaigns, personnel, and office space. Enlist the financial and marketing functions.', '11'),
('56', '20593', '3.3.3', 'Develop and manage pricing', 'Determining and maintaining a pricing mechanism based on forecasted sales and that enables a pricing equilibrium for the lifecycles of products/services. Create a pricing mechanism, factoring in attributes relating to the market, customers, sales, and the cost of production. Implement this pricing mechanism over all products/services. Analyze its performance, and adjust accordingly.', '11'),
('57', '20010', '3.3.4', 'Develop and manage promotional activities', 'Conceptualizing, testing, and executing product/service/brand promotions. Once a promotion has launched, this process continues as the organization tweaks parts of the promotion or chooses to use ideas or lessons learned during the promotion in future activities. The promotion''s performance according to organizational measures is also evaluated in this process. Determine early on whether you need third party help with promotion. Purchase lists, consult with social media experts, hire seasonal staff, or pay for additional research.', '11'),
('58', '10153', '3.3.5', 'Track customer management measures', 'Collating all customer-centered metrics. The objective is to create a big-picture view of the customers'' mindset and their behavior pertaining to the organization''s offerings.', '11'),
('59', '16613', '3.3.6', 'Analyze and respond to customer insight', 'Reviewing and responding to customer feedback. Create tickets to initiate bug fixes or to propose feature updates. Monitor and track progress.', '11'),
('60', '10154', '3.3.7', 'Develop and manage packaging strategy', 'Creating, executing, and administering a strategic road map for packaging products/services. Determine how to package products/services into finished offerings that can be directly marketed to prospective customers. Consider physicality, perishability, and shelf-life. Develop a strategy for packaging products/services. Test alternatives. Collect feedback. Refine the option chosen for execution. Have marketing, product development, and supply chain functions work together to develop sound packaging.', '11'),
('61', '16629', '3.3.8', 'Manage product marketing content', 'Creating descriptions of products that are promotional and informative in content in order to initiate and increase sales. Marketing content consists of text, and optionally, images.', '11'),
('62', '10129', '3.4.1', 'Develop sales forecast', 'Developing a sales forecast for the organization''s portfolio of offerings, bearing in mind the effect of promotional events, and fine-tuning these in the context of the new forecast. Estimate the future demand for the organization''s products/services by analyzing historical information and any promotional activity.', '12'),
('63', '10130', '3.4.2', 'Develop sales partner/alliance relationships', 'Cultivating an alliance of partners by identifying, analyzing, negotiating, and managing partnerships with other economic agents.', '12'),
('64', '10131', '3.4.3', 'Establish overall sales budgets', 'Setting up a financial plan for the sales function. Calculate the estimated sales revenue and costs, which helps in calculating the overall net profit. Create a sound plan for resource outlay by comparing the forecast with historical data.', '12'),
('165', '10523', '7.7.2', 'Manage employee inquiry process', 'Handling instances where an employee believes that he/she has been inappropriately treated or he/she desires clarification. Encourage employees to inquire when needed. Record and clarify the issues for which the enquiry has been made.', '34'),
('65', '10132', '3.4.4', 'Establish sales goals and measures', 'Establishing specific quantitative and qualitative measures of realizing sales targets. Create sales targets by analyzing historical sales data and comparing the forecasts to results, in light of customer and market intelligence. Examine the performance of sales personnel in light of market opportunities. Based on this review, establish sales targets along with metrics to quantify these goals, corresponding with the overall business strategy.', '12'),
('66', '10133', '3.4.5', 'Establish customer management measures', 'Identifying the appropriate measures that can represent key attributes of the customer management function. Select measures to track customer activity, feedback, satisfaction, organizational responsiveness to customer needs, and general data on how the organization is managing customer accounts, leads, and contacts. Build on customer and market intelligence to identify metrics gauging aspects related to customer management. Select measures based on the nature of the business, the type and size of customer base, strategic goals, and the model used to structure sales and customer relationships.', '12'),
('67', '10182', '3.5.1', 'Manage leads/opportunities', 'Generating leads of prospective customers to grow the organization''s business. Identify viable customers based on customer and market research. Discover leads through IT applications, cold calling, reference/network development, or other sales and business development techniques. Employ a scoring model qualify the prospective customers into leads, and prioritize them.', '13'),
('68', '17686', '3.5.2', 'Bid and proposal development', 'Analyzing requirements, competition, and pricing to develop bids and proposals. The organization will understand and refine the customer requirements as provided in a RFP (Request for Proposal) or RFI (Request for Information). Take into consideration whether the requirements are a match with the strategic or tactical plans of the organization and whether they are able to submit a bid/proposal that is competitive based on an understanding of the offerings of other competing organizations.  Define the pricing and scheduling of the proposed solution and determine whether the proposal will be profitable for the company if accepted.  The bid is then submitted and a notification of whether or not it was successful is received.', '13'),
('69', '10183', '3.5.3', 'Manage customers and accounts', 'Managing the customer''s expectations, with the intent of responsibly increasing the sale of the organization''s products/services. Create a systematic method for governing sales, using sales forecasts and customer management measures. Develop a blueprint to manage relationships with customers and the data it holds on them, as well as the sale of its products/services to these customers. Devise a recipe for handling the organization''s key customers in order to manage their expectations with tact and responsibility while maximizing revenue.', '13'),
('70', '11779', '3.5.4', 'Develop and manage sales proposals, bids, and quotes', 'Understanding and refining the customer requirements as provided in a RFP (Request for Proposal) or RFI (Request for Information).  When compiling the response, they must take into consideration whether the requirements are a match with the strategic or tactical plans of the organization and whether they are able to submit a bid/proposal that is competitive based on an understanding of the offerings of other competing organizations. The next step will be to define the pricing and scheduling of the proposed solution and determine whether the proposal will be profitable for the company if accepted. The bid is then submitted and a notification of whether or not it was successful is received.', '13'),
('71', '10185', '3.5.5', 'Manage sales orders', 'Taking, receiving, processing, and acknowledging new customer orders or amendments to outstanding customer orders. Monitoring status from order receipt to customer delivery/customer invoicing.', '13'),
('72', '10187', '3.5.6', 'Manage sales partners and alliances', 'Managing the organization''s partners and alliances, with the objective of maximizing revenue. Train partners regarding the organization''s portfolio of products/services. Craft sales forecasts. Examine their performance. Manage all data held by the organization on these partners.', '13'),
('73', '10221', '4.1.1', 'Develop production and materials strategies', 'Creating strategies for production processes, as well as the process of managing materials. Define production and supply constraints. Design a blueprint of the workplace. Establish rules and regulations regarding the employees, outsourcing of services, and the expenditure to be incurred on the manufacturing capital.', '14'),
('74', '10222', '4.1.2', 'Manage demand for products', 'Forecasting demand for products using secondary research and customer feedback. Refine these forecasts. Inspect the approach used in creating forecasts, and determine its accuracy.', '14'),
('75', '10223', '4.1.3', 'Create materials plan', 'Developing a scheme that allows for advance planning for the availability of raw materials and spares. Start with an unconstrained plan, and refine based on supply chain realities by identifying critical materials required for production, checking material specifications, and collaborating with all vendors over the supply.', '14'),
('76', '10224', '4.1.4', 'Create and manage master production schedule', 'Taking care of the master production plan. The master production includes creation and implementation of the site-level production plan, as well as management of the inventory that is currently in the production process.', '14'),
('77', '17042', '4.1.5', 'Plan distribution requirements', 'Maintaining master data of finished products and inventory. Identify the requirements of finished products at the destination, as well as partner requirements. Calculate the consolidation at source. Manage replenishment planning. Create and administer a dispatch plan. Calculate load plans for destinations and partners. Manage the cost of supplying these products. Ensure effective utilization of capacity.', '14'),
('78', '10226', '4.1.6', 'Establish distribution planning constraints', 'Instituting the constraints for planning of distribution process. Create a plan that specifies every element in the distribution process from the blueprint of the distribution centers to how and when the inventory would reach the distribution centers.', '14'),
('79', '10227', '4.1.7', 'Review distribution planning policies', 'Revisiting and refurbishing the policies for planning the distribution process. Asses the distribution strategies, including how the products are to be made available and sent to different distributors. Set guidelines regarding relationships between the sources and the distribution centers.', '14'),
('80', '10368', '4.1.8', 'Develop quality standards and procedures', 'Developing standards and procedures for maintaining the quality of products/services. Establish desired quality targets. Create standardized procedures for the quality. Ensure quality specifications are effectively communicated.', '14'),
('81', '10277', '4.2.1', 'Provide sourcing governance and perform category management', 'Creating strategies for procuring materials and services from various sources, and for managing and evaluating categories. Establish a procurement process that describes the approach for obtaining products and purchasing activities. Evaluate the sources. Create sourcing relationships in order to continuously improve. Re-evaluate purchasing activities. ', '15'),
('166', '10524', '7.7.3', 'Manage and maintain employee data', 'Capturing and updating employee information and data and information on the employees. ', '34'),
('82', '20973', '4.2.2', 'Develop sourcing and category management strategies', 'Deploying a strategic sourcing methodology to segment the majority of organizational spend based on external supply markets (versus individual suppliers or internal stakeholders) to reduce the cost of buying goods and services, reduce risk in the supply chain, and maximize value delivered from the supply base. This approach typically includes cross-functional management of categories, examining the entire category spend, how the organization uses the products or services within the category, the marketplace, and major suppliers. ', '15'),
('83', '10278', '4.2.3', 'Select suppliers and develop/maintain contracts', 'Evaluating supplier options to select the most effective and efficient suppliers. Validate selected suppliers. Establish and manage supplier contracts.', '15'),
('84', '10279', '4.2.4', 'Order materials and services', 'Creating and approving requisitions and distributing purchase orders accordingly. Hasten the procurement process to satisfy internal needs.', '15'),
('85', '10280', '4.2.5', 'Manage suppliers', 'Collecting and analyzing new information in order to track and rate suppliers through a supplier information management system.', '15'),
('86', '10303', '4.3.1', 'Schedule production', 'Scheduling the production of final products. Generate a detailed schedule plan. Create and release production orders and lots. Schedule the planned and unplanned maintenance orders.', '16'),
('87', '10304', '4.3.2', 'Produce/Assemble product', 'Manufacturing the product. Convert the raw materials to develop consumer-ready products. Manage the raw materials to implement the detailed production schedule. Reproduce defectives to establish and remediate cause. Ensure production optimization and benchmark performance.', '16'),
('88', '12810', '4.3.3', 'Test Product', 'Insuring compliancy of bulk, intermediate, and finished packaged products.', '16'),
('89', '12827', '4.4.1', 'Develop and maintain quality management system', NULL, '17'),
('90', '12828', '4.4.2', 'Develop quality standards and sampling procedures', NULL, '17'),
('91', '12832', '4.4.3', 'Conduct stability and validating tests and maintain test results', NULL, '17'),
('92', '12835', '4.4.4', 'Maintain batch records and manage lot traceability', NULL, '17'),
('93', '10370', '4.4.5', 'Maintain production records and manage lot traceability', 'Perpetuating the production records by systematically documenting and using it to ensure the effective management of lots. Determine the lot numbering system and its use. (The lot number enables tracking of the constituent parts, as well as labor and equipment records involved in the manufacturing of a product. It enables manufacturers and to perform quality control checks, calculate expiration dates, and issue corrections of their production output.)', '17'),
('94', '17699', '4.5.1', 'Develop Sample Delivery Tracking Program', 'Establishing a technical system to support sample delivery tracking.  Distribute medicinal samples to certified medical practitioners with safeguards.  ', '18'),
('95', '10338', '4.6.1', 'Provide logistics governance', 'Outlining the strategy for managing logistics. Translate customer requirements logistic requirements. Create an efficient logistic network and outsourcing portions of logistics activities. Design a logistics strategy that optimizes transportation costs and schedule. Define key performance indicators.', '19'),
('96', '20936', '4.6.2', 'Plan and manage inbound material flow', 'Creating and executing a strategy for all the internal activities related to the flow/transfer of inbound materials. This process includes planning inbound material receipts, managing inbound material flow, monitoring inbound delivery performance, managing the flow of returned products, controlling the quality of returned parts, and salvaging or repairing returned products.', '19'),
('97', '10340', '4.6.3', 'Operate warehousing', 'Tracking the inventory deployment. Accept and store products. Ship the products. Measure the accuracy of the inventory. Assess the performance of the outsourced logistics activities.', '19');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('98', '10341', '4.6.4', 'Operate outbound transportation', 'Creating a plan that specifies the schedule and system for transportation and delivery of the outbound products, as well as tracking the performance of the carrier delivery system. Conduct vehicle management and processing of all carrier-related documents.', '19'),
('99', '20027', '5.1.1', 'Establish service delivery governance', 'Establishing service delivery governance through a system that manages performance, development, and direction. Allow for customer feedback on delivery satisfaction.', '20'),
('100', '20032', '5.1.2', 'Develop service delivery strategies', 'Constructing strategies that identify goals, policies, processes, and procedures in relation to service delivery. Review and validate strategies. Define the workplace layout and infrastructure.', '20'),
('101', '20041', '5.2.1', 'Manage service delivery resource demand', 'Ensuring necessary resources are maintained through monitoring pipeline, developing forecasts, and collaborating with customers. Determine skills needed for service deliver and forecast customer orders. Monitor forecasted orders and modify if where needed. Measure forecast accuracy. ', '21'),
('102', '20050', '5.2.2', 'Create and manage resource plan', 'Identifying the need for and creating a resource plan. Understand resource demand and align with capacity, skills, and capabilities. Enlist suppliers and partners to supplement needed skills and capabilities. Monitor and manage capabilities and skills with an eye on critical resources and supplier capacity.', '21'),
('103', '12127', '5.2.3', 'Enable service delivery resources', 'Instituting training to enable resources to provide service delivery to the customer. Develop a training plan. Create materials that provide for operation and technical training. Schedule, perform, and evaluate training.', '21'),
('104', '20059', '5.3.1', 'Initiate service delivery', 'Collaborating with the customer to understand service needs. Review, understand, and modify the delivery scope with the organization needs of the customer in mind. Confirm readiness and identify, select, and assign resources. Plan for service delivery.', '22'),
('105', '20069', '5.3.2', 'Execute service delivery', 'Carrying out service delivery to the customer by creating and deploying the necessary solution. Analyze need and create a solution. Validate the solution and make changes if needed. Obtain approval to build/buy solution and then deploy solution to customer.', '22'),
('106', '20077', '5.3.3', 'Complete service delivery', 'Implementing final steps to complete service delivery to the customer. Evaluate success through project review, complete finance activities, and confirm delivery. Release resources and manage completion by harvesting knowledge and systems by archiving records.', '22'),
('107', '20086', '6.1.1', 'Define customer service requirements across the enterprise', 'Defining a set of behaviors, skills, and policies needed to provide customer service effectively across the enterprise.', '23'),
('108', '20087', '6.1.2', 'Define customer service experience', 'Communicating to the customer service resources what is expected when engaging the customer. Relate service level expectations to the workforce. Ensure positive customer experience. ', '23'),
('109', '20088', '6.1.3', 'Define and manage customer service channel strategy', 'Establishing and refining procedures for customer service and technical support.', '23'),
('110', '10382', '6.1.4', 'Define customer service policies and procedures', 'Outlining the framework of policies and methods for developing customer service strategy. Establish the rules and regulations that serve as a guideline for the customer service strategy. Take into account customer needs and behavior.', '23'),
('111', '10383', '6.1.5', 'Establish target service level for each customer segment', 'Determining and implementing levels for customer services. Benchmark certain customer service practices, and base customer level services on those benchmarks. Create a service level agreement, which is a negotiated agreement designed to create a common understanding about services, priorities, and responsibilities.', '23'),
('112', '12839', '6.1.6', 'Establish and manage plans to comply with HIPAA and other customer regulations', NULL, '23'),
('113', '20089', '6.1.7', 'Define warranty offering', 'Determining the exact terms and conditions under which specific warranties apply to certain goods or services.', '23'),
('114', '20092', '6.1.8', 'Develop recall strategy', 'Establishing procedures to handle recalls of defective products.', '23'),
('115', '10387', '6.2.1', 'Plan and manage customer service work force', 'Creating and administering the work force deployed for the customer service process. Forecast the customer work force needs to correctly schedule the work force. Track the utility of the work force deployed. Examine the interactions between the customer and customer service representatives to achieve high quality.', '24'),
('116', '10388', '6.2.2', 'Manage customer service problems, requests, and inquiries', 'Handling the requests and inquiries from customers that seek information regarding the organization''s products/services. Obtain the customer requests online and by phone. Direct these requests to higher-level representatives. Approve requests, and respond to customers.', '24'),
('117', '10389', '6.2.3', 'Manage customer complaints', 'Obtaining customer complaints online or by phone. Direct these complaints to higher-level representatives as appropriate. Resolve them. Respond to customers.', '24'),
('118', '12840', '6.2.4', 'Report incidents, adverse events, and Corrective Action Preventive Action (CAPA)', 'Notifying all stakeholders, legal, and industry regulatory bodies of the incidents and risks related to a return or recall, if needed. ', '24'),
('119', '12846', '6.2.5', 'Manage medical inquiries', 'Facilitating activities to receive, assign, track, and respond to medical enquiries. ', '24'),
('120', '12851', '6.2.6', 'Authorize and manage product returns', 'Verifying, authorizing, and processing of returns and receipt of returned products.   This builds on Manage returns; manage reverse logistics [10342] and includes customer-focused activities related to the  receipt of return requests, authorization of returns, submission of returns to the customer, and verification of receipt of returned goods.', '24'),
('121', '20605', '6.3.1', 'Register products', 'Filing product registrations.', '25'),
('122', '12669', '6.3.2', 'Process warranty claims', 'Identifying, investigating, and processes warranty claims. This process includes: receipt and validation of a warranty claim; definition and diagnosis /root cause analysis of an issue and recommendation for corrective action; the determination of responsibility for settlement of the claim; the transaction being approved or denied; and the originator being notified and payment authorized. In the case of a recurring event, further investigation (definition and diagnosis or root cause analysis) is performed, and a recommendation for corrective action is made and implemented in production/design. It ends when the claim is closed.', '25'),
('123', '20106', '6.3.3', 'Manage supplier recovery', 'Managing the recovery of costs from suppliers for individual claims.', '25'),
('124', '10218', '6.3.4', 'Service products', 'Validating specific service requirements for individual customers. Determine and schedule resource to fulfill these requirements. Provide service to specific individual customers. Ensure the quality of service delivery.', '25'),
('125', '20111', '6.4.1', 'Initiate recall', 'Commencing the removal process of defective products.', '26'),
('126', '20112', '6.4.2', 'Assess the likelihood and consequences of occurrence of any hazards', 'Performing risk analysis. Identify all dangers, evaluate how probable they are, and what kinds of negative results or or adverse side effect they carry.', '26'),
('127', '20113', '6.4.3', 'Manage recall related communications', 'Handling communications that are related to product recalls.', '26'),
('128', '20114', '6.4.4', 'Submit regulatory reports', 'Creating and delivering reports to regulatory agencies to provide details about handling product recalls. ', '26'),
('129', '20115', '6.4.5', 'Monitor and audit recall effectiveness', 'Analyzing the effectiveness of product recalls.', '26'),
('130', '20116', '6.4.6', 'Manage recall termination', 'Ending product recalls, communicating to the public and filing reports.', '26'),
('131', '10401', '6.5.1', 'Measure customer satisfaction with customer problems, requests, and inquiries handling', 'Calculating satisfaction levels of customers by effectively evaluating the process of handling requests/inquiries of customers. Effectively calculate the performance of customer-requests/inquiries handling and resolution. Obtain information regarding requests/inquiries handling and resolution through customer feedback. Use it to explore new ideas and opportunities for enhanced customer requests/inquiries handling and resolution process.', '27'),
('132', '10402', '6.5.2', 'Measure customer satisfaction with customer- complaint handling and resolution', 'Measuring the satisfaction level of customers as pertains to how their complaints are handled and resolved. This process element requires the organization to estimate the customers level of fulfillment with the process reconciling their complaints and towards the objective of ensuring customer retention. The feedback received can be used to develop concepts for new opportunities to boost the level of customer satisfaction.', '27'),
('133', '10403', '6.5.3', 'Measure customer satisfaction with products and services', 'Calculating satisfaction levels of customers with products/services. Obtain customer feedback on products/services, as well as the effectiveness of the advertising campaigns. Examine this information to reach meaningful conclusions, which could then be used to enhance the customer service operations.', '27'),
('134', '12672', '6.5.4', 'Evaluate and manage warranty performance', 'Assessing the cost and effectiveness of warranties. ', '27'),
('135', '20121', '6.5.5', 'Evaluate recall performance', 'Reviewing customer service feedback to identify areas in which improvements can be made. Engage with management to discuss issues.', '27'),
('136', '20958', '7.1.1', 'Develop human resources strategy', 'Creating a long-term plan to associate human resource requirements with the strategic goals of the company to ensure that there is enough qualified staffing to achieve those goals, to maintain competitive advantage and to reduce employee turnover.', '28'),
('137', '17045', '7.1.2', 'Develop and implement workforce strategy and policies', 'Creating and executing strategies and policies for smooth administration of work force. Determine and gather skill requirements. Plan the requirements for employee resourcing per unit. Create compensation, succession, HR program, and employee diversity plans. Develop and administer policies for HR. Develop benefits for employees. Create models for work force strategies.', '28'),
('138', '10417', '7.1.3', 'Monitor and update strategy, plans, and policies', 'Supervising the HR strategy, plans, and policies in order to refurbish them whenever needed. Determine the performance of HR plans and policies by measuring the objective achievement rate and its contribution to the overall business strategy. Ensure that information about these plans and strategies is effectively communicated to various stakeholders. Incorporate any suggestions by these stakeholders when revising HR plans and policies.', '28'),
('139', '17046', '7.1.4', 'Develop competency management models', 'Creating and implementing the tools for managing the competency levels of HR. Design a model for integrating HR planning with business planning. Assess current HR capacity based on the competencies against the capacity needed to achieve the vision, mission, and business goals of the organization. Consider factors such as employee development, career path, compensation policies, and performance management.', '28'),
('140', '10439', '7.2.1', 'Manage employee requisitions', 'Handling the requirements for new employees. Create and open job requisitions by clearly defining the job descriptions. Post these requirements internally and externally, and modify them as appropriate. Manage the dates of the whole requisition process.', '29'),
('141', '10440', '7.2.2', 'Recruit/Source candidates', 'Recruiting new candidates for deployment across various functional areas inside the organization. Select methods for sourcing new employees. Manage relationships with third-party agencies. Stage recruitment fairs and drives. Manage employee referral programs.', '29'),
('142', '20123', '7.2.3', 'Screen and select candidates', 'Evaluating and selecting potential employees through interviews, tests, etc.', '29'),
('143', '10443', '7.2.4', 'Manage new hire/re-hire', 'Creating and making job offers to the selected candidates. Fairly negotiate the job offers. Agree on terms with the candidate to complete the hiring process.', '29'),
('144', '10444', '7.2.5', 'Manage applicant information', 'Creating and maintaining a system for managing the information of applicants. Create records for all candidates who apply. Maintain and track information through the use applicant-tracking systems.', '29'),
('145', '10469', '7.3.1', 'Manage employee orientation and deployment', 'Creating and maintaining various employee on-boarding programs typically known as induction programs in order to ensure that the new employees are effectively introduced to the organization and its existing employees. Examine and evaluate the performance of these induction programs. Execute these programs on the ground level.', '30'),
('146', '10470', '7.3.2', 'Manage employee performance', 'Defining individual performance objectives. Review performance in order to provide appraisals. Evaluate the efficiency and effectiveness of the current performance program. Update it regularly.', '30'),
('147', '10472', '7.3.3', 'Manage employee development', 'Establishing employee development guidelines. Lay out career paths and plans for them. Manage the development of their skills to enhance their skills, ability, and knowledge.', '30');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('148', '10473', '7.3.4', 'Develop and train employees', 'Creating a link between employee and organizational development needs. Conduct and manage employee training programs by considering the need and availability of these programs. ', '30'),
('149', '10483', '7.4.1', 'Manage labor relations', 'Managing labor relations, the collective bargaining process, and the relationships between the labor and management. Take care of employee grievances.', '31'),
('150', '10484', '7.4.2', 'Manage collective bargaining process', 'Managing any negotiations between an employer and a group of employees that determine the conditions of employment. Engage employees to reach agreements in regulating working conditions. ', '31'),
('151', '10485', '7.4.3', 'Manage labor management partnerships', 'Handling partnerships between labor and management. Develop a lasting two-way relationship that is beneficial for the labor, management, and the organization.', '31'),
('152', '10531', '7.4.4', 'Manage employee grievances', 'Taking care or resolving any complaint raised by an employee by procedures provided for in a collective agreement, an employment contract, or by other mechanisms established by an employer.', '31'),
('153', '10494', '7.5.1', 'Develop and manage reward, recognition, and motivation programs', 'Developing a salary/compensation structure and plan; developing a benefits and reward plan; develop commission plan; performing competitive analyses of benefits and rewards; identifying compensation requirements based on compensation, benefits, and HR policies; administering compensation, commission, and rewards to employees; and rewarding and motivating employees.', '32'),
('154', '10495', '7.5.2', 'Manage and administer benefits', 'Managing and ensuring benefits enrollment by the employees. Process any benefit claims made by the employees. Balance the estimated amount and entitled amount of benefits.', '32'),
('155', '10496', '7.5.3', 'Manage employee assistance and retention', 'Managing activities centered around delivering programs to support work/life balance for employees; developing family support systems; reviewing retention and motivation indicators; and reviewing compensation plans.', '32'),
('156', '10497', '7.5.4', 'Administer payroll', 'Managing the sum of all financial records of salaries for an employee, including wages, bonuses, and deductions. Use a payroll management system to deal with the financial aspects of employees'' salaries, allowances, deductions, gross pay, net pay, etc. Generate pay slips for a specific period.', '32'),
('157', '10512', '7.6.1', 'Manage promotion and demotion process', 'Administering the process of promoting and demoting employees. Design a system for advancing or demoting an employee''s rank or position. Leverage techniques such as horizontal promotion, vertical promotion, dry promotion, and involuntary/voluntary demotion.', '33'),
('158', '10513', '7.6.2', 'Manage separation', 'Managing the process of employee separation, including resignations, discharges, and layoffs. Inform the employee of the termination. Complete paperwork for continuation of benefits.', '33'),
('159', '10514', '7.6.3', 'Manage retirement', 'Managing and administering instances where a person stops employment completely.', '33'),
('160', '10515', '7.6.4', 'Manage leave of absence', 'Managing the period of time that an employee must be away from their primary job, while maintaining the status of employee (i.e., paid and unpaid leave of absence but not vacations, holidays, hiatuses, sabbaticals, and work-from-home programs).', '33'),
('161', '10516', '7.6.5', 'Develop and implement employee outplacement', 'Helping former employees transition to new jobs or to re-orient themselves in the job market. Deliver help through one-on-one sessions or in a group format. Provide guidance in career evaluation, resume writing, interview preparation, developing networks, and job searching.', '33'),
('162', '20132', '7.6.6', 'Manage workforce scheduling', 'Organizing the workforce so that all positions are covered for all shifts with the necessary skilled resources in place. Have a system in place to backfill positions while an employee is on leave.', '33'),
('163', '17055', '7.6.7', 'Relocate employees and manage assignments', 'Managing the relocation of employees in order to carry out assignments. Manage internal business processes to transfer employees, their families, and/or entire departments of a business to a new location.', '33'),
('167', '10525', '7.7.4', 'Manage human resource information systems HRIS', 'Administering and maintaining HR information systems that take care of activities related to HR, accounting, management, and payroll.', '34'),
('168', '10526', '7.7.5', 'Develop and manage employee metrics', 'Creating and maintaining performance metrics for employees. Create and manage a strategic system of data and statistics to accurately gauge each employee''s information. Consider productivity metrics, efficiency metrics, training metrics, etc.', '34'),
('169', '10527', '7.7.6', 'Develop and manage time and attendance systems', 'Developing and maintaining systems for managing the time and attendance of employees. Routinely upgrade the process and systems that track when employees start and stop work, the department where the work is performed, attendance in addition to tracking meals and breaks, the type of work performed, and the number of items produced.', '34'),
('170', '10530', '7.7.7', 'Manage/Collect employee suggestions and perform employee research', 'Procuring and handling suggestions from employees, and performing research on employees. Manage and analyze the programs that help the organization to tap into employee ideas for improving the organization''s processes and/or products. Use surveys, focus groups, and other data-gathering methods to find out the attitudes, opinions, and feelings of members of an organization.', '34'),
('171', '10529', '7.8.1', 'Develop employee communication plan', 'Creating a plan for managing communication among employees. Inform employees of direction. Counter resistance with change management approaches. Seek specific areas of input to the decision-making process. Seek varying degrees of involvement and co-creation.', '35'),
('172', '16944', '7.8.2', 'Conduct employee engagement surveys', 'Questioning employees to ascertain overall workplace satisfaction. ', '35'),
('173', '12860', '7.10.1', 'Evaluate union relations internally', NULL, '37'),
('174', '12861', '7.10.2', 'Evaluate union relations externally', NULL, '37'),
('175', '12862', '7.10.3', 'Optimize relations', NULL, '37'),
('176', '12863', '7.10.4', 'Monitor relations', 'Optimizing and monitoring ongoing union relations.  Conduct internal and external evaluations of union relationships.', '37'),
('177', '20609', '8.1.1', 'Understand IT customer needs', 'Assessing the customer communities along with current IT operational capabilities and usage. ', '38'),
('178', '20612', '8.1.2', 'Identify IT customer transformation needs', 'Identifying changing needs of staff dependent on information technology based on continuous improvement to deliver results according to organizational goals.', '38'),
('179', '20617', '8.1.3', 'Plan and communicate IT services', 'Create and design an organized and curated collection of all IT-related services that can be performed by, for, or within the organization. Maintain and convey information about deliverables, prices, contact points, and processes for requesting an information technology service.', '38'),
('180', '20623', '8.1.4', 'Provide IT transformation guidance', 'Understanding the necessity of IT transformation for the business. Collect and analyze customer requirements. Identify opportunities and prioritize outcomes. Develop and support business case for transformation. Develop transformation plan and roadmap. ', '38'),
('181', '20632', '8.1.5', 'Develop and manage IT service levels', 'Establishing and maintaining service levels for the provision of IT services and solutions. Design and maintain the IT services and solution catalogue, as well as service level agreements. Evaluate the performance of IT service level agreements. Communicate the results to the management.', '38'),
('182', '20641', '8.1.6', 'Manage IT customer relationships', 'Managing the IT relationship with its customers by systematically coordinating interactions over multiple touch points on a regular basis. Coordinate the IT''s efforts to reach out to its customers, which include emails, social-media interactions, newsletters, and direct conversations.', '38'),
('183', '20648', '8.1.7', 'Analyze service performance', 'Proactively manage IT service levels against IT customer requirements.', '38'),
('184', '20653', '8.2.1', 'Define business technology and governance strategy', 'Defining the need of technology in business and systematic implementation of IT investments. It comprises of assessing competitive technology components to ensure structural analysis, development, usage and security of technology for efficient business operations.', '39'),
('185', '20660', '8.2.2', 'Manage IT portfolio strategy', 'Strategy for systematic management of IT investments, projects, and activities. Analyze and examine the value of the IT portfolio and allocate resources based on business objectives.', '39'),
('186', '20668', '8.2.3', 'Define and maintain enterprise architecture', 'Outlining and maintaining the organization''s IT architecture. Establish the IT architecture definition and framework. Ensure the relevance of IT. Create and confirm the approach for IT maintenance. Create rules and regulations to guide IT architecture. Authenticate and finalize all IT related research and innovation that takes place within the organization.', '39'),
('187', '20674', '8.2.4', 'Define IT service management strategy', 'Defining perspective, position, plans, and patterns needed to execute designing, delivering, managing, and improving the way information technology is used within an organization.', '39'),
('188', '20682', '8.2.5', 'Control IT management system', 'Regulating the IT management system through performance measures, governance, analysis, and monitoring through a variety of analytic tools. Evaluate IT finances, resource, services, projects, and value for report out. ', '39'),
('189', '20693', '8.2.6', 'Manage IT value portfolio', 'Creating and establishing the value portfolio. Defining, analyzing, and examining the value of projects, investments, and activities of the IT function.', '39'),
('190', '20699', '8.2.7', 'Define and manage technology innovation', 'Outline and manage the innovation of technology within the organization. Research and understand emerging future technological concepts and capabilities. Plan for IT innovation investments. Plan and execute viable innovation projects.', '39'),
('191', '20707', '8.3.1', 'Develop IT compliance, risk, and security strategy', 'Ensuring that the organization effectively manages risk. Develop rules and standards for robust IT operations, manage risk, and adopt measures to protect integrity, confidentiality, and security of IT assets. ', '40'),
('192', '20716', '8.3.2', 'Develop IT resilience strategy', 'Developing resilience strategies of IT across the organization so that prospective risks can be avoided.', '40'),
('193', '20721', '8.3.3', 'Control IT risk, compliance, and security', 'Ensure effective control in overall IT risk management, formulate and execute guidelines in-line with regulatory bodies, and manage organizational security throughout the business operations.', '40'),
('194', '20731', '8.3.4', 'Plan and manage IT continuity', 'Planning and managing IT''s ability to recover from exposure to internal and external threats.', '40'),
('195', '20735', '8.3.5', 'Develop and manage IT security, privacy, and data protection', 'Creating and deploying an architecture for securing and ensuring the privacy of data flows throughout the organization. Create and develop protocols that ensure proper and efficient use of IT services and solutions', '40'),
('278', '10952', '10.4.1', 'Develop exit strategy', 'Creating a strategy for managing asset exits. ', '59'),
('196', '20743', '8.3.6', 'Conduct and analyze IT compliance assessments', 'Evaluate and analyze the IT environment for the compliance of industry regulations and government legislation. Ensure that IT capability and resources meet the set standards.', '40'),
('197', '20749', '8.3.7', 'Develop and execute IT resilience and continuity operations', 'Create and execute a process to rapidly adapt and respond to any internal or external opportunity, demand, disruption, or threat in IT. Maintain continuous IT operations to protect employees, assets, and overall brand equity.', '40'),
('198', '20756', '8.3.8', 'Manage IT user identity and authorization', 'The process of identifying, authenticating, and authorizing IT users to have access to applications, systems, IT components, or networks by associating user rights and restrictions with established identities.', '40'),
('199', '20766', '8.4.1', 'Define business information and analytics strategy', 'Create an organization-wide strategy for the IT function by combining skills, technologies, applications, and processes in order to attain organizations objectives.', '41');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('200', '20770', '8.4.2', 'Define and maintain business information architecture', 'Creating strategies to manage the organization''s information and content. Outline the architecture for information collection and communication. Administer information resources, data management and content.', '41'),
('201', '20776', '8.4.3', 'Define and execute business information lifecycle planning and control', 'Develop and implement strategies to plan and manage the flow of an information system''s data from creation and initial storage to the time when it becomes obsolete and deleted.', '41'),
('202', '20779', '8.4.4', 'Manage business information content', 'Creating strategies to administer information and content. Understand the needs of the organization for information and content management. Realize the role of IT services for implementing the overall business strategy. Assess the implications of new technologies for managing information and content. Identify and prioritize the most effective and efficient actions for managing information and content.', '41'),
('203', '20785', '8.5.1', 'Develop service/solution and integration strategy', 'Developing service/solution along with creating a strategy that provides a base for delivering service/solution aligned with overall business needs. Conduct research within the services/solutions field for development and integration.', '42'),
('204', '20793', '8.5.2', 'Manage service/solution lifecycle planning', 'Executing life-cycle planning for IT services and solutions. Develop new requirements and feature-function enhancements. Create and design a life cycle plan that addresses the current and future state of IT services and solutions.', '42'),
('205', '20799', '8.5.3', 'Develop and manage service/solution architecture', 'Creating the architecture for the IT services and solutions. Assess architecture and business constraints in order to understand integration requirements. Promote existing architecture. Manage exceptions.', '42'),
('206', '20808', '8.5.4', 'Execute IT service/solution creation and testing', 'Understanding customer requirements. Design the IT services and solutions based on the requirements. Develop components for providing the requirements. Train resources to provide support. Test the IT services and solutions in advance. Confirm the customer experience post-sale.', '42'),
('207', '20817', '8.5.5', 'Perform service/solution maintenance and testing', 'Engaging in all aspects of service/solution maintenance and testing includes all preventative, routine, and corrective activates. Ensure that IT service/solution are functioning properly and regulations where applicable.', '42'),
('208', '20825', '8.6.1', 'Develop and manage service/solution deployment strategy', 'Creating and implementing a strategy for the deployment of IT service/solution. Define all of the activities that make the IT function available for use. Establish the change policies for IT services and solutions. Define the deployment process, procedures, and tools. Select the most feasible and practical methodologies for the deployment process.', '43'),
('209', '20832', '8.6.2', 'Plan service and solution implementation', 'Strategizing and executing changes in IT solutions and services. Create a plan for deploying the changes. Communicate with stakeholders about the changes. Administer and implement the changes. Train the resources who will be affected by these changes. Install changes and verify their effect.', '43'),
('210', '20840', '8.6.3', 'Manage change deployment control', 'Creating and deploying an architecture for securing the changes deployed in the organization. Create and develop protocols that ensure proper and efficient use of deployed IT services and solutions. Test, evaluate, and implement the policies and protocols.', '43'),
('211', '20848', '8.6.4', 'Implement technology solutions', 'Deploy the identified solutions for information technology important for healthy business operations. Confirm status and operational availability of IT resources. Perform testing and distribution of change. Execute roll-back protocol if necessary.', '43'),
('212', '20858', '8.6.5', 'Perform service and solution rollout', 'Strategizing and executing changes in IT solutions and services. Create a plan for deploying the changes. Communicate with stakeholders about the changes. Administer and implement the changes. Train the resources who will be affected by these changes. Install changes and verify their effect.', '43'),
('213', '20867', '8.7.1', 'Define and establish service delivery strategy', 'Defining and establishing strategy for delivering IT services and solutions to the users. Design an IT service delivery model that defines the processes and procedures needed to deliver the IT services and solutions.', '44'),
('214', '20873', '8.7.2', 'Define and develop service support strategy', 'Defining and creating a strategy for provision of support to users of IT services and solutions. ', '44'),
('215', '20880', '8.7.3', 'Plan and manage service delivery control', 'Determine and manage service delivery flow across different business functions. Understand the level of services needed by different stakeholders. Identify major service delivery touch points and criticality associated. Ensure timely communication with users.', '44'),
('216', '20888', '8.7.4', 'Develop and manage infrastructure resource planning', 'Developing and managing the resources required for administration of infrastructure. Manage the IT inventory and assets to meet organization''s IT resource capacity.', '44'),
('217', '20895', '8.7.5', 'Define service support planning', 'Develop strategies and methodologies to provide service support. Examine service levels, support complexity, stakeholder requirements to offer service support.', '44'),
('218', '20905', '8.7.6', 'Develop and manage service delivery operations', 'Developing and managing different delivery services using service delivery systems for operational activities within the IT function in order to achieve organizations goal.', '44'),
('219', '20914', '8.7.7', 'Manage infrastructure resource administration', 'Managing the resources required for administration of IT infrastructure. Manage the IT inventory and assets. Take care of the organization''s IT resource capacity. ', '44'),
('220', '20921', '8.7.8', 'Operate IT user support', 'Managing systematic user support functionality and capability through defined procedures. Determine, record, and monitor user requests. Execute issue/request resolution. Utilize escalation path when needed. Resolve issue/request. ', '44'),
('221', '10738', '9.1.1', 'Perform planning/budgeting/forecasting', 'Allocating funds to meet future and current financial goals. Led by the chief financial officer, have the finance function plan, budget, and forecast in order to determine and describe long and short-term financial goals.', '45'),
('222', '10739', '9.1.2', 'Perform cost accounting and control', 'Defining costs to be incurred and methods for optimum utilization. Determine the costs of products, processes, projects, etc. to compile in the financial statements, as well as to assist management in making decisions regarding planning and control. Control costs by managing and reducing business expenses.', '45'),
('223', '10740', '9.1.3', 'Perform cost management', 'Deciding which expenses can be avoided to reduce some costs and increase revenues. Plan and control the organization''s budget to forecast future expenditures. ', '45'),
('224', '10741', '9.1.4', 'Evaluate and manage financial performance', 'Checking and achieving predetermined financial targets and timelines. Assess and manage the profitability, feasibility, and consistency of a business or project. Study the revenues generated.', '45'),
('225', '10742', '9.2.1', 'Process customer credit', 'Evaluating and processing requests for advances. Evaluate credit requests by customers requiring loans to buy products/services. ', '46'),
('226', '10743', '9.2.2', 'Invoice customer', 'Preparing detailed reports of customer purchases. Prepare a commercial document between the seller and customer with details about transaction. Detail the quantity purchased, price of products/services, date, parties involved, unique invoice number, and tax information.', '46'),
('227', '10744', '9.2.3', 'Process accounts receivable (AR)', 'Processing payments due from customers. This includes all processing of funds received, whether by check or electronically. This does not include the generation of invoices.', '46'),
('228', '10745', '9.2.4', 'Manage and process collections', 'Posting entries to respective accounts, and preparing accounts for receivables. Manage the cash collected by the business from its debtors. Record it in the books of accounts to provide clear information about the availability of the cash.', '46'),
('229', '10746', '9.2.5', 'Manage and process adjustments/deductions', 'Creating and providing funds for necessary adjustments and deductions, including all expenses that were required for the business at certain point in time.', '46'),
('230', '10747', '9.3.1', 'Manage policies and procedures', 'Creating procedures to perform general accounting and reporting. Follow the rules and regulations made for a particular process in the business. Publish accounting policies. ', '47'),
('231', '10748', '9.3.2', 'Perform general accounting', 'Applying basic principles, concepts, and accounting practices in recording and preparing final accounts, and using accounting information in management.', '47'),
('232', '10749', '9.3.3', 'Perform fixed-asset accounting', 'Accounting for long-term and fixed assets. Record purchased, fixed assets that are not easily convertible into cash. Account for costs, useful life, resale value, depreciation, and amortization.', '47'),
('233', '10750', '9.3.4', 'Perform financial reporting', 'Reporting on the organization''s financial status to stakeholders. Include balance sheets, income statements, cash flow statements, and statements of shareholders'' equity.', '47'),
('234', '10751', '9.4.1', 'Perform capital planning and project approval', 'Preparing a project finance report to solicit approvals in capital projects. Prepare budgets for projects that require heavy investments. Report on project finances to solicit approvals from management.', '48'),
('235', '10752', '9.4.2', 'Perform capital project accounting', 'Accounting for large-scale and large-cost investments. Manage and account for ongoing activities related to capital projects, including setting up new projects, recording project transactions, monitoring and tracking spending, closing and capitalizing projects, and measuring the financial returns on completed projects.', '48'),
('236', '10753', '9.5.1', 'Report time', 'Recording the reporting time of employees on-site. Track working days, salary calculations, holidays taken, number of hours spend in the office, billing hours, etc.', '49'),
('237', '10754', '9.5.2', 'Manage pay', 'Managing the total payments made in employees payroll, including bonuses and compensation.', '49'),
('238', '10755', '9.5.3', 'Manage and process payroll taxes', 'Deducting and paying taxes from employees'' salaries.', '49'),
('239', '10756', '9.6.1', 'Process accounts payable (AP)', 'Processing payments of operating expenses and other supplier charges. This includes the development of policies and procedures around processing of accounts payable and all operations. This process is often supported by key technology enablers.', '50'),
('240', '10757', '9.6.2', 'Process expense reimbursements', 'Processing reimbursements to employees for the expenses incurred during the course of business. Approve and process advancements and reimbursements for employee expenses on the organization''s behalf. Capture and report relevant tax data and manage personal accounts. ', '50'),
('241', '20929', '9.6.3', 'Manage corporate credit cards', 'Handling and authoring credit cards to business entities or for corporate purchases.', '50'),
('242', '10758', '9.7.1', 'Manage treasury policies and procedures', 'Managing rules and regulations for investments in trading in bonds, currencies, financial derivatives, etc. Establish policies and procedures for investments made. Optimize liquidity in treasury operations.', '51'),
('243', '10759', '9.7.2', 'Manage cash', 'Taking care of all cash-related activities in the business. Manage and reconcile cash positions. Manage cash equivalents. Process and oversee electronic fund transfers. Develop cash flow forecasts. Manage cash flows. Produce cash management accounting transactions and reports. Manage and oversee banking relationships. Analyze, negotiate, resolve, and confirm bank fees.', '51'),
('244', '10760', '9.7.3', 'Manage in-house bank accounts', 'Managing financial services provided by an in-house bank structure in the corporation that is operating like a commercial bank. ', '51'),
('245', '10761', '9.7.4', 'Manage debt and investment', 'Taking care of the organization''s financial position. Manage its loans or debts from different sources and investments. Leverage the most profitable options to balance the financial position in the market.', '51'),
('246', '11208', '9.7.5', 'Monitor and execute risk and hedging transactions', 'Performing transactions that limit investment risk with the help of derivatives, such as options and futures contracts. Manage interest rates, foreign exchange, and exposure risks. Develop and execute hedging transactions. Evaluate and refine hedging positions. Produce hedge accounting transactions and reports. Monitor credit.', '51'),
('247', '16958', '9.7.6', 'Manage financial fraud/dispute cases', 'Handling cases that involve financial fraud. Resolve disputes.', '51'),
('248', '10762', '9.8.1', 'Establish internal controls, policies, and procedures', 'Forming rules and regulations to ensure the achievement of effectiveness, proficiency of operations, and reliability of financial reporting.', '52'),
('279', '19258', '10.4.2', 'Decommission productive assets', 'Retiring assets that are no longer viable to the business. Decommission assets that are no longer in working order, are out of date, or whose maintenance exceeds the cost of replacement.', '59');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('249', '10763', '9.8.2', 'Operate controls and monitor compliance with internal controls policies and procedures', 'Incorporating planning, management, operations, and monitoring of internal control mechanism policies and procedures in order to manage internal controls. Design and implement control activities. Monitor control effectiveness. Remediate control deficiencies. Create compliance functions. Operate compliance functions. Implement and maintain technologies and tools to enable the internal controls-related activities.', '52'),
('250', '10764', '9.8.3', 'Report on internal controls compliance', 'Reporting on internal controls compliance to the appropriate authority, including IT regulations and pertinent data.', '52'),
('251', '10765', '9.9.1', 'Develop tax strategy and plan', 'Setting targets for periodic tax liabilities. Assess the tax impact of various activities such as the acquisition or disposal of fixed assets or a deliberate change in number of employee.', '53'),
('252', '10766', '9.9.2', 'Process taxes', 'Processing the taxes of the organization in line with the regional taxation structure, including corporate, property, excise, and service taxes.', '53'),
('253', '10767', '9.10.1', 'Monitor international rates', 'Forecasting and monitoring changes in foreign currency value or interest rates around the world that play an important role in the organization.', '54'),
('254', '10768', '9.10.2', 'Manage transactions', 'Managing any transfer of funds in the course of conducting cross-border trades or investments, including conversion across currencies. Find the most suitable alternative for making payments, while saving taxes and avoiding any unwarranted regulation, with the objective of protecting capital.', '54'),
('255', '10769', '9.10.3', 'Monitor currency exposure/hedge currency', 'Assessing exposure to potential financial losses as a result of changes in the value of currencies. Forecast the impact of movements in foreign currency values. Enter into financial transactions designed to offset or limit potential exposure to loss.', '54'),
('256', '10770', '9.10.4', 'Report results', 'Documenting and reporting accounting entries to formally report financial gains or losses experienced as a result of foreign exchange activity.', '54'),
('257', '14090', '9.11.1', 'Screen sanctioned party list', 'Evaluating the approved list of parties for engaging in international trade in order to ensure the safety of the organization''s business transactions. Examine agents that have been granted legal rights to engage in global trade and their credentials.', '55'),
('258', '14091', '9.11.2', 'Control exports and imports', 'Overseeing and directing the flow of trade to/from the organization in order to ensure financial gains. ', '55'),
('259', '14092', '9.11.3', 'Classify products', 'Systematically categorizing products/services for their suitability to international trade. Create classes and categories for demarcating the types of products suitable for international trade. Study requisite national and international standards and the adherence of the organization''s portfolio of offerings to these.', '55'),
('260', '19593', '9.11.4', 'Perform currency conversion', 'Identifying current exchange rates between two currencies and converting the foreign currency to that of the local monetary unit. I.E., yen to US dollar. ', '55'),
('261', '14093', '9.11.5', 'Calculate duty', 'Computing the excise duty to be paid during international trade.', '55'),
('262', '14094', '9.11.6', 'Communicate with customs', 'Communicating with the customs department to ensure fluid compliance. Share pertinent information mandated by law with the government agency that controls and collects the duties levied for the international exchange of products/services.', '55'),
('263', '14095', '9.11.7', 'Document trade', 'Documenting and recording the trade processes while making transactions, noting the description, quality, number, transportation medium, indemnity, and inspection.', '55'),
('264', '14096', '9.11.8', 'Process trade preferences', 'Preparing global trade under preference, which allows the organization to import/export products at a lower or nil rate of customs duty and/or levy charge.', '55'),
('265', '14097', '9.11.9', 'Handle restitution', 'Administering and overseeing all restitution activities the organization may be subjected to. Manage compliance with apposite legal frameworks. Make any restitution that may be required by law; comply with authorities over any fines or non-financial measures imposed.', '55'),
('266', '14098', '9.11.10', 'Prepare letter of credit', 'Creating a document assuring that a seller will receive payment when certain delivery conditions are met. (If the buyer is unable to make payment on the purchase, a bank covers the outstanding amount.)', '55'),
('267', '10941', '10.1.1', 'Develop property strategy and long term vision', 'Strategizing a long-term vision for managing properties. Prepare strategies and a long-term vision for managing purchased/retained properties.', '56'),
('268', '10943', '10.1.2', 'Plan facility', 'Recognizing the needs of facility users in order to construct a project proposal that meets those needs.', '56'),
('269', '10944', '10.1.3', 'Provide workspace and facilities', 'Managing the provision of the workspace and its assets. Arrange an office space with all assets (tables, chairs, computers, admin staff, etc.) according to requirements.', '56'),
('270', '10949', '10.1.4', 'Manage facilities operations', 'Managing all operational activities of the facility. Manage how each function/business unit works. Support the manufacturing facility to attain organizational goals.', '56'),
('271', '19209', '10.2.1', 'Manage capital program for productive assets', 'Producing and maintaining a planning schedule and a financial plan to purchase or manufacture productive assets. Determine the investment plan, monitor capital, and secure the necessary financing in order to realize completion of the program.', '57'),
('272', '20139', '10.2.2', 'Design and plan asset construction', 'Outlining the steps and strategies needed to construct assets. Verify that all regulations are adhered to and that all permissions have been granted. Organize and plan for resources to complete construction.', '57'),
('273', '19229', '10.2.3', 'Schedule and perform construction work', 'Arranging a timetable for which to perform construction work. Schedule resources to contract assets for new or replacement assets. Reschedule or redesign assets if needed. ', '57'),
('274', '19224', '10.2.4', 'Manage asset construction', 'Overseeing the performance and quality of work. Assure that records are maintained throughout the construction process. Adhere to all safety, security, and access regulations set forth by the organization and all government standards. ', '57'),
('275', '19239', '10.3.1', 'Plan asset maintenance', 'Ensuring that necessary resources are available and tasks are prioritized accordingly through planning. Provide strategies and policies that identify tasks that need to be completed, and the resources necessary to fulfill those tasks.', '58'),
('276', '19245', '10.3.2', 'Manage asset maintenance', 'Ensuring that asset maintenance is conducted in a timely manner and successfully. Schedule work with the required resources with an eye on quality control and safety. Verify that contracted maintenance meets performance targets.', '58'),
('277', '19253', '10.3.3', 'Perform asset maintenance', 'Engaging in all aspects of asset maintenance. Ensure that all assets are functioning properly and to all specified codes and regulations where applicable. Maintenance includes all preventative, routine, and corrective activates.', '58'),
('280', '10953', '10.4.3', 'Perform sale or trade', 'Performing the sale of assets. Achieve and complete the sale process. Deliver the end product to the customers. ', '59'),
('281', '10954', '10.4.4', 'Perform abandonment', 'Abandoning assets. Manage the act of deliberately and permanently giving up, granting, leaving, or surrendering property or buildings and allowing others to use the intellectual property without protest.', '59'),
('282', '16970', '10.4.5', 'Perform waste and hazardous goods management', 'Disposing of waste and hazardous materials as outlined by state, local, and federal regulations.', '59'),
('283', '16439', '11.1.1', 'Establish the enterprise risk framework and policies', 'Creating an agenda for the rules and regulations of enterprise risk that deal with hazardous, financial, operational, and strategic risks.', '60'),
('284', '16445', '11.1.2', 'Oversee and coordinate enterprise risk management activities', 'Coordinating to plan, organize, lead, and control the activities of an organization in order to minimize the special effects of risk on capital and earnings.', '60'),
('285', '17462', '11.1.3', 'Manage business unit and function risk', 'Analyzing the threats a business unit/function faces to prioritize the controls it implements.. ', '60'),
('286', '17468', '11.2.1', 'Establish compliance framework and policies', 'Developing a set of procedures detailing an organization''s progress in complying with established guidelines, provisions, and legislation.', '61'),
('287', '16463', '11.2.2', 'Manage regulatory compliance', 'Obeying laws, guidelines, strategies, and stipulations related to the business.', '61'),
('288', '11201', '11.3.1', 'Create remediation plans', 'Creating plans for remediation efforts. Make a plan to address a case of environmental adulteration. Identify and treat the adulteration so that the area will become operational again.', '62'),
('289', '11202', '11.3.2', 'Contact and confer with experts', 'Discussing and soliciting advice from experts for in order to incorporate their suggestion (regarding Create remediation plans [11201]).', '62'),
('290', '11203', '11.3.3', 'Identify/dedicate resources', 'Identifying and dedicating the resources for managing remediation efforts. Discern the resources needed for remediation efforts. Dispense with resources in a sound and well-reasoned manner.', '62'),
('291', '11204', '11.3.4', 'Investigate legal aspects', 'Examining regulatory and legislative frameworks. Obligate the organization to remediate any damages through compensations, fines, and any other remedial efforts necessitated to correct the situations. Analyze local environmental laws, binding international covenants, etc. in order to examine legal accuracy about the rules and procedures.', '62'),
('292', '11205', '11.3.5', 'Investigate damage cause', 'Studying the causes of damage, which could be environmental, physical, social, etc. at country level in order to institute better policies and regulations.', '62'),
('293', '11206', '11.3.6', 'Amend or create policy', 'Crafting a new framework of policies and procedures for deploying remediation efforts, or change existing policies and procedures. Adapt the policy structure to the context of the apposite national and international regulatory frameworks.', '62'),
('294', '11221', '11.4.1', 'Develop the business resilience strategy', 'Creating a strategy for rapidly adapting to disturbances. Maintain continuous business processes and protecting employees, assets, and overall brand equity.', '63'),
('295', '11222', '11.4.2', 'Perform continuous business operations planning', 'Developing plans to ensure continuous business operations. ', '63'),
('296', '11223', '11.4.3', 'Test continuous business operations', 'Assessing ongoing activities within the organization that are not intended to stop except for in an emergency. ', '63'),
('297', '11224', '11.4.4', 'Maintain continuous business operations', 'Evaluating business operations. Determine which activities generate revenues, perform best, and provide good returns.', '63'),
('298', '16471', '11.4.5', 'Share knowledge of specific risks across other parts of the organization', 'Sharing information about risks and resilience strategies of business operations across the organization so that prospective risks can be avoided. ', '63'),
('299', '11035', '12.1.1', 'Plan, build, and manage lender relations', 'Building and managing relations with bankers or lenders through strong products/services strategies that bankers would want to invest in. Foster a receptive environment for low rates of interest, easy access to loans, etc.', '64'),
('300', '11036', '12.1.2', 'Plan, build, and manage analyst relations', 'Creating and maintaining long-term relations with analysts. Involve analysts in strategy and product decisions in order to elicit valuable information.', '64');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('301', '11037', '12.1.3', 'Communicate with shareholders', 'Practicing regular, transparent communication with shareholders through annual shareholders'' meetings, quarterly earnings calls, shareholders letters, one-on-one emails or calls, etc.', '64'),
('302', '11038', '12.2.1', 'Manage government relations', 'Persuading public and government policy at the local, regional, national, and global level (subject to government regulations).', '65'),
('303', '11039', '12.2.2', 'Manage relations with quasi-government bodies', 'Managing relations with quasi-governmental organizations, corporations, businesses, or any other agency that is treated by national laws and principles to be under the supervision of the government but also distinct and self-directed from the government.', '65'),
('304', '11040', '12.2.3', 'Manage relations with trade or industry groups', 'Managing relations with organizations established and financed by businesses that operate in a specific industry. Participate in public relations actions such as lobbying and publishing, advertising, education, and political donations.', '65'),
('305', '11041', '12.2.4', 'Manage lobby activities', 'Managing lobbying activities to affect government policies. ', '65'),
('306', '11042', '12.3.1', 'Report financial results', 'Reporting financial results to management, and releasing results to the public. Report financial statements, including the income statement, balance sheet, and statement of cash flows.', '66'),
('307', '11043', '12.3.2', 'Report audit findings', 'Reporting audit findings to management. Practice an internal audit with criteria for confirming a problem, a description of the situation, and the root cause of the problem. Make recommendations that resolve the issue.', '66'),
('308', '11044', '12.4.1', 'Create ethics policies', 'Creating a code of ethics that communicate the organization''s philosophy to employees, vendors, customers, clients, and the public.', '67'),
('309', '11045', '12.4.2', 'Manage corporate governance policies', 'Administering the system of rules, practices, and processes through which a company is directed and controlled. Balance stakeholder interests including shareholders, management, customers, suppliers, financiers, government, and the community. Outline a strategy for achieving organizational goals, from action plans and internal controls to performance measurement and corporate disclosure.', '67'),
('310', '11046', '12.4.3', 'Develop and perform preventive law programs', 'Creating and applying programs and activities. Encourage the adherence preventive laws, such as environmental law, sex discrimination, computer law, estate planning, corporate compliance, business planning, and property transactions.', '67'),
('311', '11047', '12.4.4', 'Ensure compliance', 'Ensuring the organization''s compliance position. Validate compliance with different statutes, regulatory directions, and legal principles (using Establish compliance framework and policies [17468]). Coordinate with compliance and risk management personnel.', '67'),
('312', '11048', '12.4.5', 'Manage outside counsel', 'Managing professionals, sought externally for assistance over legal and ethical concerns. Administer and oversee assistance from subject matter experts and professionals for sourcing expert opinion and counseling over legal and ethical matters.', '67'),
('313', '11049', '12.4.6', 'Protect intellectual property', 'Safeguarding the intellectual property of the organization. This process requires the organization to protect a wide variety of intellectual property created by it. It involves creating and managing non-disclosure agreements (NDAs), following up on current developments in the areas where the organization holds patents, tracking the use of the organization''s copyrighted material, creating and upholding licensing terms, and administering policies for safeguarding intellectual property.', '67'),
('314', '11050', '12.4.7', 'Resolve disputes and litigations', 'Resolving disputes or civil lawsuits internally or externally. ', '67'),
('315', '11051', '12.4.8', 'Provide legal advice/counseling', 'Providing legal advice concerning the substance or procedure of a law in relation to a particular situation.', '67'),
('316', '11052', '12.4.9', 'Negotiate and document agreements/contracts', 'Negotiating terms to reach a final draft of a contract that is acceptable to all parties. ', '67'),
('317', '11066', '12.5.1', 'Manage community relations', 'Developing and administering community relations. Establish business connections with the people constituting the environment the organization operates in and draws resources from in order to foster mutual understanding, trust, and support. Create programs that promote the organization''s image in a positive and community-oriented way.', '68'),
('318', '11067', '12.5.2', 'Manage media relations', 'Developing and managing relations with media. Develop connections with journalists to solicit critical, third-party endorsements for a product, issue, service, or organization.', '68'),
('319', '11068', '12.5.3', 'Promote political stability', 'Promoting political security and stability in the regions where the organization conducts business. Encourage political stability in the regions where the organization operates. Support civic programs, citizen engagement, connection platforms, etc.', '68'),
('320', '11069', '12.5.4', 'Create press releases', 'Developing press releases to communicate developments and generate interest in the organization. ', '68'),
('321', '11070', '12.5.5', 'Issue press releases', 'Issuing press releases to carefully selected media in distribution channels such as the web, newspapers, and social media.', '68'),
('322', '16379', '13.1.1', 'Establish and maintain process management governance', 'Defining and managing the organization''s approach to governing business process management. Establish and manage tools to support the governance process. Assign ownership for all business processes. Perform activities to administer the governing process.', '69'),
('323', '16384', '13.1.2', 'Define and manage process frameworks', 'Determining and organizing the structural composition of business processes. Design, establish, and administer the framework. Identify any cross-functional processes that are mandatory for achieving business excellence.', '69'),
('324', '16387', '13.1.3', 'Define processes', 'Outlining and establishing the business processes of the organization. Scope, analyze, map, and publish processes for the employees who may require it.', '69'),
('325', '16392', '13.1.4', 'Manage process performance', 'Evaluating and handling the performance of business processes. Provide training to process owners. Support the execution of business processes. Measure and report the performance of the business processes.', '69'),
('326', '16396', '13.1.5', 'Improve processes', 'Identifying and choosing improvement opportunities. Create and manage improvement projects. Perform the improvement activities continuously and routinely. ', '69'),
('327', '16401', '13.2.1', 'Manage portfolio', 'Managing the business portfolio of the organization, including investments, holdings, products, businesses, and brands. Establish a portfolio strategy. Define portfolio governance. Monitor and control the portfolio.', '70'),
('328', '16405', '13.2.2', 'Manage programs', 'Establishing, implementing, and managing business programs. Successfully handle related projects that together constitute a program. Establish the program structure and approach. Coordinate with stakeholders and partners. Execute the program. Assess and report the performance of the program. Coordinate and prioritize resources across projects. Manage links between the projects and the overall costs and risks of the program.', '70'),
('329', '16410', '13.2.3', 'Manage projects', 'Establishing the scope of the projects. Create plans for implementing the projects. Initiate projects. Review and report project performance to management. Close projects.', '70'),
('330', '17472', '13.3.1', 'Establish quality requirements', 'Determining essential activities, processes, and attributes for securing enterprise quality. Outline critical characteristics for quality. Outline activities encouraging the preservation of quality. Create quality controls. Confirm capabilities in accordance with quality requirements. Finalize the plan for quality maintenance.', '71'),
('331', '17482', '13.3.2', 'Evaluate performance to requirements', 'Analyzing if the performance of the quality plan has achieved the estimated and desired requirements. Conduct tests against the quality plan. Assess the results of these tests.', '71'),
('332', '17492', '13.3.3', 'Manage non-conformance', 'Handling any nonconformance activities or events. Assess the potential impact of the nonconformity. Decide the immediate actions to take. Identify the root causes. Take corrective or preventive action. Ensure future conformance.', '71'),
('333', '17498', '13.3.4', 'Implement and maintain the enterprise quality management system (EQMS)', 'Establishing and administering the software that manages content and business processes for quality and compliance across the value chain. Define the quality strategy. Plan and deploy the EQMS scope, targets, and goals. Identify core process controls and metric. Develop EQMS governance. Assess the performance of EQMS. Encourage improvements in EQMS.', '71'),
('334', '11134', '13.4.1', 'Plan for change', 'Crafting a plan for implementing change to the organization''s multiple frameworks, systems, and functional areas. Chart a schematic plan that gives the organization a foundation to shape its change efforts.', '72'),
('335', '11135', '13.4.2', 'Design the change', 'Developing plans for change management, training, communication, and rewards/incentives. Establish metrics for measuring the change adoption. Clarify new roles for employees. Identify budgets.', '72'),
('336', '11136', '13.4.3', 'Implement change', 'Effectuating the change within the desired impact areas of the organization. Ensure adequate commitment from all corners of the organization for the desired change. Create support structures. Refashion all processes deemed necessary. Observe the progress.', '72'),
('337', '11137', '13.4.4', 'Sustain improvement', 'Sustaining the impact of the change process in order to enact continual process improvement. Monitor the performance of re-engineered business processes. Identify best practices and potential issues. Effectuate remedial steps.', '72'),
('338', '11095', '13.5.1', 'Develop KM strategy', 'Creating a plan for managing the organization''s knowledge base. Determine what kind of specialized knowledge the organization possesses, which elements of this collective knowledge can prove beneficial, how to capture and maintain this knowledge, how to grant access to this library of information, and how the organization should proceed.', '73'),
('339', '11096', '13.5.2', 'Assess KM capabilities', 'Assessing the maturity of the existing initiatives in knowledge management, and evaluating existing KM approaches. Identify the gaps and needs in order to enhance the existing KM approaches. Develop and implement new KM approaches.', '73'),
('340', '20965', '13.5.3', 'Design and implement KM capabilities', 'Creating knowledge bases and other repositories to preserve and develop company expertise, and to train new employees.', '73'),
('341', '20969', '13.5.4', 'Evolve and sustain KM capabilities', 'Developing resources for improved knowledge management and knowledge engineering.', '73'),
('342', '11071', '13.6.1', 'Create and manage organizational performance strategy', 'Creating and implementing a strategy for administering organizational performance. This process element calls upon the organization to create and administer a strategy for measuring, tracking, streamlining, and improving internal performance. It encompasses creating a blueprint for the tactical measurement of internal processes and work force improvement, in alignment with Employee Metrics Developed and Managed [10526].', '74'),
('343', '11072', '13.6.2', 'Benchmark performance', 'Comparing organizational performance internally or externally with other organizations. ', '74'),
('344', '20147', '13.6.3', 'Evaluate process performance', 'Assessing process data, measures, and trends in an effort to evaluate process performance and identify possible improvements.', '74'),
('345', '11180', '13.7.1', 'Determine environmental health and safety impacts', 'Determining the impact of EHS offering--and the procedures it employs to process them--on the environment at large, as well as the health and safety of employees. Evaluate the environmental impact of the organization''s products, services, and operations. Conduct health, safety, and environmental audits.', '75'),
('346', '11181', '13.7.2', 'Develop and execute functional EHS program', 'Identify the requirements for regulation and shareholders. Assess future risks and opportunities. Develop a policy for the EHS program. Record and manage EHS program events.', '75'),
('347', '11182', '13.7.3', 'Train and educate functional employees', 'Conducting programs such as on-the-job training sessions, group training workshops, and online training.', '75'),
('348', '11183', '13.7.4', 'Monitor and manage functional EHS management program', 'Managing the costs and benefits of EHS. Measure and report the performance of EHS. Implement plans for emergency response and pollution prevention. Provide EHS support. ', '75'),
('349', '20960', '13.8.1', 'Develop and manage hypotheses', 'Creating theories that explain empirical data. Use the hypotheses to guide feature selection in the process of data collection.', '76'),
('350', '20961', '13.8.2', 'Collect data', 'Gathering and harvesting structured and unstructured data from disparate sources. Clean and pre-process data. Remove duplicates. Convert to a uniform format to make records comparable.', '76');
INSERT INTO automation_hub.apqc_process (id, pcf_id, hierarchy_id, name, description, process_group_id) VALUES
('351', '20962', '13.8.3', 'Analyze data', 'Conducting data analysis. Choose statistical algorithms that best reveal patterns and trends in the data. Compare with hypotheses and time series forecasts. Determine error rates and significant outliers. ', '76'),
('352', '20963', '13.8.4', 'Report on data', 'Summarizing and documenting the results of data analysis. Create graphs and visualizations to illustrate numerical findings to make them more accessible to readers.', '76'),
('353', '20964', '13.8.5', 'Identify remedial actions', 'Determining the steps that need to be taken to correct the shortcomings.', '76');
INSERT INTO automation_hub.idea (id, title, submitter_name, apqc_process_id, primary_goal, process_stability, system_stability, task_frequency, transaction_volume, headcount_fte, avg_time_per_task_minutes, error_rate_pct, avg_rework_time_minutes, audit_rate_pct, avg_loaded_fte_cost_eur, number_of_steps, decision_logic, process_variations, primary_input_format, number_of_systems, system_interface, unstructured_data, cognitive_reasoning, computer_vision, ai_output_risk, annual_transactions, base_hours, rework_hours, total_hours_saved, gross_roi_eur, feasibility_score, feasibility_band, technology_category, final_classification, status, created_at) VALUES
